/// "rum = 12" -> Some(("rum", 12)); None if the line is damaged.
fn parse_entry(line: &str) -> Option<(&str, u32)> {
    let Some((name, count)) = line.split_once('=') else {
        return None;
    };
    let name = name.trim();
    if name.is_empty() {
        return None;
    }
    let count = count.trim().parse().ok()?;
    Some((name, count))
}

/// The count for `name`, or "no crate named <name>".
fn count_of(entries: &[(&str, u32)], name: &str) -> Result<u32, String> {
    entries
        .iter()
        .find(|(n, _)| *n == name)
        .map(|&(_, count)| count)
        .ok_or_else(|| format!("no crate named {name}"))
}

/// The count, or 0 if the ink is smudged.
fn count_or_zero(s: &str) -> u32 {
    s.trim().parse().unwrap_or_default()
}

fn main() {
    let lines = ["rum = 12", "maps = 3", "parrots = many"];
    let entries: Vec<(&str, u32)> = lines.iter().filter_map(|l| parse_entry(l)).collect();
    println!("{entries:?}");
    println!("{:?}", count_of(&entries, "maps"));
    println!("{}", count_or_zero("lots"));
}

