use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum CargoError {
    Empty,
    MissingCount(String),
    BadCount(ParseIntError),
}

impl fmt::Display for CargoError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            CargoError::Empty => write!(f, "empty line"),
            CargoError::MissingCount(line) => write!(f, "no count in {line:?}"),
            CargoError::BadCount(e) => write!(f, "bad count: {e}"),
        }
    }
}

impl From<ParseIntError> for CargoError {
    fn from(e: ParseIntError) -> Self {
        CargoError::BadCount(e)
    }
}

fn parse_line(line: &str) -> Result<(String, u32), CargoError> {
    let line = line.trim();
    if line.is_empty() {
        return Err(CargoError::Empty);
    }
    let Some((name, count)) = line.split_once(':') else {
        return Err(CargoError::MissingCount(line.to_string()));
    };
    let count: u32 = count.trim().parse()?;
    Ok((name.trim().to_string(), count))
}

fn total(manifest: &str) -> Result<u32, CargoError> {
    let mut sum = 0;
    for line in manifest.lines() {
        let (_, count) = parse_line(line)?;
        sum += count;
    }
    Ok(sum)
}

fn main() {
    match parse_line("rum: 12") {
        Ok((name, count)) => println!("{count} x {name}"),
        Err(e) => println!("error: {e}"),
    }
    match total("rum: 12\nmaps: x") {
        Ok(sum) => println!("total {sum}"),
        Err(e) => println!("error: {e}"),
    }
}

