#[cfg(test)]
mod hidden_tests {
    use super::*;

    #[test]
    fn parses_name_and_count() {
        let (name, count) = parse_line("  sea maps : 12 ").unwrap();
        assert_eq!(name, "sea maps");
        assert_eq!(count, 12);
    }

    #[test]
    fn blank_line_is_empty_error() {
        assert!(matches!(parse_line("   "), Err(CargoError::Empty)));
    }

    #[test]
    fn missing_colon_keeps_the_trimmed_line() {
        match parse_line("  rum 12 ") {
            Err(CargoError::MissingCount(line)) => assert_eq!(line, "rum 12"),
            other => panic!("expected MissingCount, got {other:?}"),
        }
    }

    #[test]
    fn bad_count_wraps_the_parse_error() {
        assert!(matches!(parse_line("rum: lots"), Err(CargoError::BadCount(_))));
        assert!(matches!(parse_line("rum: -3"), Err(CargoError::BadCount(_))));
    }

    #[test]
    fn display_messages_are_exact() {
        assert_eq!(CargoError::Empty.to_string(), "empty line");
        assert_eq!(parse_line("rum 12").unwrap_err().to_string(), "no count in \"rum 12\"");
        assert_eq!(parse_line("rum: lots").unwrap_err().to_string(), "bad count: invalid digit found in string");
    }

    #[test]
    fn from_parse_int_error_gives_bad_count() {
        let e = "x".parse::<u32>().unwrap_err();
        assert!(matches!(CargoError::from(e), CargoError::BadCount(_)));
    }

    #[test]
    fn total_sums_every_line() {
        assert_eq!(total("rum: 12\nmaps: 3\ngold:0").unwrap(), 15);
        assert_eq!(total("").unwrap(), 0);
    }

    #[test]
    fn total_stops_at_first_bad_line() {
        let err = total("rum: 1\nmaps 3\ngold: x").unwrap_err();
        assert_eq!(err.to_string(), "no count in \"maps 3\"");
        assert!(matches!(total("rum: 1\n\ngold: 2"), Err(CargoError::Empty)));
    }
}

