use std::fmt;
use std::io::{self, Read};
use std::num::ParseIntError;

#[derive(Debug)]
enum MapError {
    Shape(String),
    UnknownDirection(String),
    BadDistance(ParseIntError),
}

impl fmt::Display for MapError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            MapError::Shape(line) => write!(f, "expected DIR DISTANCE, got {line:?}"),
            MapError::UnknownDirection(dir) => write!(f, "unknown direction {dir:?}"),
            MapError::BadDistance(e) => write!(f, "bad distance: {e}"),
        }
    }
}

impl From<ParseIntError> for MapError {
    fn from(e: ParseIntError) -> Self {
        MapError::BadDistance(e)
    }
}

/// One trimmed, non-blank line: how far it moves east (x) and north (y).
fn parse_step(line: &str) -> Result<(i64, i64), MapError> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    let [dir, dist] = parts[..] else {
        return Err(MapError::Shape(line.to_string()));
    };
    let (dx, dy) = match dir {
        "N" => (0, 1),
        "S" => (0, -1),
        "E" => (1, 0),
        "W" => (-1, 0),
        _ => return Err(MapError::UnknownDirection(dir.to_string())),
    };
    let dist = i64::from(dist.parse::<u32>()?);
    Ok((dx * dist, dy * dist))
}

/// Follows the whole map: (steps, x, y), or the 1-based line number and its error.
fn follow(text: &str) -> Result<(usize, i64, i64), (usize, MapError)> {
    let (mut steps, mut x, mut y) = (0, 0, 0);
    for (i, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let (dx, dy) = parse_step(line).map_err(|e| (i + 1, e))?;
        x += dx;
        y += dy;
        steps += 1;
    }
    Ok((steps, x, y))
}

fn main() -> io::Result<()> {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text)?;
    match follow(&text) {
        Ok((steps, x, y)) => {
            println!("{steps} steps followed");
            println!("treasure at ({x}, {y})");
        }
        Err((line, e)) => println!("map damaged at line {line}: {e}"),
    }
    Ok(())
}
